mapper.update:
UPDATE emoji_mapping
SET description = #{description},
    source      = #{source}
WHERE id = #{id}

mapper.select:
SELECT id, platform, bot_id AS botId, group_id AS groupId, fingerprint,
description, source, updated_at AS updatedAt, created_at AS createdAt
FROM emoji_mapping

    AND platform = #{platform}
    AND bot_id = #{botId}
    AND group_id = #{groupId}

        AND (fingerprint LIKE CONCAT('%', #{keyword}, '%') OR description LIKE CONCAT('%', #{keyword}, '%'))


ORDER BY updated_at DESC, id DESC
LIMIT #{limit} OFFSET #{offset}

SELECT COUNT(*) FROM emoji_mapping

    AND platform = #{platform}
    AND bot_id = #{botId}
    AND group_id = #{groupId}

        AND (fingerprint LIKE CONCAT('%', #{keyword}, '%') OR description LIKE CONCAT('%', #{keyword}, '%'))
